 private static readonly DateTimeOffset Now=DateTimeOffset.UtcNow;
 private static readonly DocumentMonitorScope Scope=new("T001",["foreign-customer"]);
 private static readonly string Hash=new('a',64);
 private static EvidenceVersionRecord Row(string version="version-one",string? tenant="T001",string customer="customer-one",string document="document-one")=>new(document,version,"evidence-"+version,customer,0,"MANUAL_UPLOAD","statement.pdf","application/pdf","private-reference",Hash,Now,Now,20,"private-storage-key","private-storage-version",tenant,new(Hash,"1.4.6","27800",Now.AddHours(-1),Now));
 private static Task<EvidenceSaveResult> Save(InMemoryEvidenceRepository repo,EvidenceVersionRecord row)=>repo.SaveVersionAsync(new("CreateDocumentVersion","1.0.0",row.CustomerId,"op-"+row.DocumentVersionId),row,_=>[],default);
 private static ProcessingRecord Processing(string id="processing-one",string? tenant="T001",ProcessingState state=ProcessingState.Completed)=>new(id,"version-one","evidence-version-one","customer-one","ProcessDocument","1.0.0",id,id,null,null,null,state,null,null,false,1,null,null,Now,[new("fact-private","customer-one","INCOME","PRIVATE_LABEL",999999,"INR",new(2026,10,1),"private-source",1,"evidence-version-one","version-one","1","1")],tenant);
 [Fact]public async Task ActualIntakeRetainsTrustedTenantAndOriginalHistoricalScanWithoutRerunningOrExposingContents()
 {
  var repo=new InMemoryEvidenceRepository();var content=new ReferenceEvidenceContentStore();var bytes="statement"u8.ToArray();var check=FixtureMalwareScanner.Check(bytes);var descriptor=content.StageScanned("monitor-operation",bytes,"text/plain",check);var app=new EvidenceApplication(repo,content,new CapturingTelemetry(),TimeProvider.System);var security=Vs02TestContext.Security() with{Workload=new("workspace","local-uat-workspace:T001")};var payload=Vs02TestContext.CreateVersionPayload() with{ContentReference=descriptor.Reference,ContentSha256=descriptor.Sha256};var request=Vs02TestContext.Request(Vs02ContractNames.CreateDocumentVersion,payload,"request-monitor","key-monitor",security);var result=await app.CreateDocumentVersionAsync(request);Assert.Equal(ContractOutcome.Success,result.Outcome);var original=(await repo.GetVersionAsync(payload.DocumentVersionId,default))!;Assert.Equal("T001",original.TenantId);Assert.Equal(check,original.MalwareCheck);Assert.True(DocumentMonitoring.Scanned(original));Assert.Equal(ContractOutcome.Success,(await app.CreateDocumentVersionAsync(request)).Outcome);Assert.Single((await repo.MonitorAsync(new("T001",[]),new(),default)).Items);
 }
 [Theory][InlineData(null,"customer-one")][InlineData("T002","customer-one")][InlineData("T001","foreign-customer")]
 public async Task LegacyForeignAndKnownForeignSourcesAreNotAssignedToTheAdministratorTenant(string? tenant,string customer){var repo=new InMemoryEvidenceRepository();await Save(repo,Row(tenant:tenant,customer:customer));Assert.Empty((await repo.MonitorAsync(Scope,new(),default)).Items);Assert.Null(await repo.MonitorReadAsync(Scope,"version-one",default));}
 [Theory][InlineData("hash")][InlineData("engine")][InlineData("stale")][InlineData("future")][InlineData("missing")]
 public async Task MissingOrInvalidHistoricalScanIsNeverReportedVerified(string mode){var row=Row();row=row with{MalwareCheck=mode=="missing"?null:row.MalwareCheck! with{ContentSha256=mode=="hash"?new('b',64):Hash,EngineVersion=mode=="engine"?"bad":"1.4.6",CheckedAt=mode=="stale"?Now.AddMinutes(-6):mode=="future"?Now.AddMinutes(2):Now}};var repo=new InMemoryEvidenceRepository();await Save(repo,row);var view=(await repo.MonitorReadAsync(Scope,row.DocumentVersionId,default))!;Assert.Equal("UNRECORDED",view.ScanStatus);Assert.Null(view.ScanEvidence);}
 [Fact]public async Task OwnerSupportsFullVersionHistoryLiteralSearchScanCustomerFiltersCountsAndStableBoundedPages(){var repo=new InMemoryEvidenceRepository();for(var i=0;i<111;i++)await Save(repo,Row("version-"+i.ToString("D3",CultureInfo.InvariantCulture)));var page=await repo.MonitorAsync(Scope,new(),default);Assert.Equal(111,page.Total);Assert.Equal(111,page.VerifiedAtIntake);Assert.Equal(50,page.Items.Count);var next=await repo.MonitorAsync(Scope,new(After:page.NextCursor),default);Assert.Equal(50,next.Items.Count);Assert.Empty(page.Items.Select(x=>x.DocumentVersionId).Intersect(next.Items.Select(x=>x.DocumentVersionId)));Assert.Equal(111,(await repo.MonitorAsync(Scope,new(DocumentId:"document-one"),default)).Matching);Assert.Empty((await repo.MonitorAsync(Scope,new("%"),default)).Items);Assert.Empty((await repo.MonitorAsync(Scope,new(Scan:"UNRECORDED"),default)).Items);Assert.Empty((await repo.MonitorAsync(Scope,new(CustomerId:"other"),default)).Items);Assert.Equal(111,(await repo.MonitorAsync(Scope,new("STATEMENT"),default)).Matching);Assert.Equal(111,(await repo.GetDocumentAsync("document-one",default)).Count);}
 [Fact]public async Task ExistingDocumentAndOperationCannotChangeRecordedSourceTenant(){var repo=new InMemoryEvidenceRepository();await Save(repo,Row());await Assert.ThrowsAsync<InvalidOperationException>(()=>Save(repo,Row(tenant:"T002")));await Assert.ThrowsAsync<InvalidOperationException>(()=>Save(repo,Row("version-two",tenant:"T002")));Assert.Single((await repo.MonitorAsync(Scope,new(),default)).Items);}
 [Fact]public async Task ActualHttpInventoryDetailAndClassificationProjectionExposeOnlyOperationalMetadata(){await using var h=await Host.Start();var page=await h.Client.GetFromJsonAsync<DocumentMonitorPage>("/local/v1/administration/documents");Assert.Single(page!.Items);var row=await h.Client.GetFromJsonAsync<MonitoredDocument>("/local/v1/administration/documents/version-one");Assert.Equal("VERIFIED_AT_INTAKE",row!.ScanStatus);var response=await h.Client.GetAsync("/local/v1/administration/document-classifications?customerId=customer-one&versionId=version-one");Assert.Equal(HttpStatusCode.OK,response.StatusCode);Assert.Equal("no-store",response.Headers.CacheControl!.ToString());var item=Assert.Single((await response.Content.ReadFromJsonAsync<ClassificationMonitorPage>())!.Items);Assert.Equal(["INCOME"],item.DetectedCategories);var body=await response.Content.ReadAsStringAsync();foreach(var value in new[]{"999999","PRIVATE_LABEL","CandidateValue","private-reference","private-source","Facts"})Assert.DoesNotContain(value,body,StringComparison.OrdinalIgnoreCase);var metadata=await h.Client.GetStringAsync("/local/v1/administration/documents/version-one");Assert.DoesNotContain("private-storage",metadata,StringComparison.Ordinal);Assert.DoesNotContain("private-reference",metadata,StringComparison.Ordinal);Assert.Equal(HttpStatusCode.NotFound,(await h.Client.GetAsync("/local/v1/administration/documents/foreign-version")).StatusCode);}
 [Theory][InlineData("?tenantId=T002")][InlineData("?limit=500")][InlineData("?search=x&search=y")][InlineData("?scan=CLEAN")][InlineData("?scan=")][InlineData("?customerId=bad%20id")][InlineData("?documentId=bad%20id")][InlineData("?after=unknown")][InlineData("?search=%20padded")]
 public async Task InventoryRejectsUnboundedForeignDuplicateOrInvalidQueries(string query){await using var h=await Host.Start();Assert.Equal(HttpStatusCode.BadRequest,(await h.Client.GetAsync("/local/v1/administration/documents"+query)).StatusCode);}
 [Theory][InlineData(401)][InlineData(403)][InlineData(503)]public async Task EveryOwnerReadRequiresCurrentAdministrator(int status){await using var h=await Host.Start();h.Authority.Status=status;Assert.Equal((HttpStatusCode)status,(await h.Client.GetAsync("/local/v1/administration/documents")).StatusCode);Assert.Equal((HttpStatusCode)status,(await h.Client.GetAsync("/local/v1/administration/document-classifications?customerId=customer-one&versionId=version-one")).StatusCode);}
 [Fact]public async Task PostReadRevocationChangedAuthorityAndCrossOriginCannotExposeMetadata(){await using var h=await Host.Start();h.Authority.DenyAfter=1;Assert.Equal(HttpStatusCode.Forbidden,(await h.Client.GetAsync("/local/v1/administration/documents")).StatusCode);h.Authority.DenyAfter=int.MaxValue;h.Authority.Calls=0;h.Authority.ChangeAfter=1;Assert.Equal(HttpStatusCode.Conflict,(await h.Client.GetAsync("/local/v1/administration/documents/version-one")).StatusCode);h.Client.DefaultRequestHeaders.Add("Origin","https://foreign.example");Assert.Equal(HttpStatusCode.Forbidden,(await h.Client.GetAsync("/local/v1/administration/documents")).StatusCode);}
 [Theory][InlineData("?customerId=customer-one")][InlineData("?versionId=version-one")][InlineData("?customerId=customer-one&versionId=version-one&limit=500")][InlineData("?customerId=customer-one&versionId=version-one&after=unknown")]
 public async Task ClassificationQueriesRequireExactBoundedSourceIdentity(string query){await using var h=await Host.Start();Assert.Equal(HttpStatusCode.BadRequest,(await h.Client.GetAsync("/local/v1/administration/document-classifications"+query)).StatusCode);}
 [Theory][InlineData(ProcessingState.Accepted)][InlineData(ProcessingState.Running)][InlineData(ProcessingState.Completed)][InlineData(ProcessingState.Failed)]public async Task ClassificationExposesRealOwnerStatesWithoutClaimingSuccessfulProcessing(ProcessingState state){var repo=new InMemoryDocumentProcessingRepository();await repo.AcceptAsync(Processing(state:state),default);var row=Assert.Single((await repo.MonitorAsync("T001","customer-one","version-one",null,default)).Items);Assert.Equal(state.ToString(),row.State);}
 [Fact]public async Task ClassificationIsTenantCustomerVersionBoundAndHasPagedHistory(){var repo=new InMemoryDocumentProcessingRepository();for(var i=0;i<111;i++)await repo.AcceptAsync(Processing("processing-"+i.ToString("D3",CultureInfo.InvariantCulture)),default);await repo.AcceptAsync(Processing("foreign","T002"),default);var page=await repo.MonitorAsync("T001","customer-one","version-one",null,default);Assert.Equal(50,page.Items.Count);var next=await repo.MonitorAsync("T001","customer-one","version-one",page.NextCursor,default);Assert.Equal(50,next.Items.Count);Assert.Empty(page.Items.Select(x=>x.ProcessingId).Intersect(next.Items.Select(x=>x.ProcessingId)));Assert.Empty((await repo.MonitorAsync("T001","other","version-one",null,default)).Items);Assert.Empty((await repo.MonitorAsync("T001","customer-one","other",null,default)).Items);Assert.Single((await repo.MonitorAsync("T002","customer-one","version-one",null,default)).Items);}
 [Fact]public async Task ForgedRepositoryRowsFailClosed(){await using var h=await Host.Start(true);Assert.Equal(HttpStatusCode.ServiceUnavailable,(await h.Client.GetAsync("/local/v1/administration/documents")).StatusCode);}
 [Fact]public async Task ContractIngressCannotForgeSourceWorkloadTenantBeforeOwnerExecution(){await using var h=await Host.Start();var security=Vs02TestContext.Security("customer-one") with{Workload=new("workspace","local-uat-workspace:T002")};var request=Vs02TestContext.Request(Vs02ContractNames.CreateDocumentVersion,Vs02TestContext.CreateVersionPayload() with{CustomerId="customer-one"},"request-forged","key-forged",security);var response=await h.Client.PostAsJsonAsync("/contracts/cid-020/v1",request);Assert.Equal(HttpStatusCode.Forbidden,response.StatusCode);Assert.Contains("WORKLOAD_TENANT_MISMATCH",await response.Content.ReadAsStringAsync(),StringComparison.Ordinal);}
 private sealed class Corrupt(IDocumentMonitoringRepository inner):IDocumentMonitoringRepository
 {public async Task<DocumentMonitorPage> MonitorAsync(DocumentMonitorScope scope,DocumentMonitorQuery query,CancellationToken ct){var page=await inner.MonitorAsync(scope,query,ct);return page with{Items=[page.Items[0] with{TenantId="T002"}]};}public Task<MonitoredDocument?> MonitorReadAsync(DocumentMonitorScope scope,string version,CancellationToken ct)=>inner.MonitorReadAsync(scope,version,ct);}
 private sealed class Authority:HttpMessageHandler
 {public int Status=200,Calls,DenyAfter=int.MaxValue,ChangeAfter=int.MaxValue;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;var status=Calls>DenyAfter?403:Status;return Task.FromResult(new HttpResponseMessage((HttpStatusCode)status){Content=JsonContent.Create(status==200?(object)new TenantAdminContext("T001",Calls>ChangeAfter?"A901":"A900",1,"TenantAdmin"):new{error="ADMINISTRATOR_REQUIRED"})});}}
 private sealed class Host(WebApplication app,HttpClient client,Authority authority):IAsyncDisposable
 {public HttpClient Client=>client;public Authority Authority=>authority;public static async Task<Host> Start(bool corrupt=false){var repo=new InMemoryEvidenceRepository();await Save(repo,Row());await Save(repo,Row("foreign-version","T002","foreign-customer","foreign-doc"));await Save(repo,Row("legacy-version",null,document:"legacy-doc"));var processing=new InMemoryDocumentProcessingRepository();await processing.AcceptAsync(Processing(),default);await processing.AcceptAsync(Processing("foreign-processing","T002"),default);var authority=new Authority();var builder=WebApplication.CreateBuilder();builder.Logging.ClearProviders();builder.WebHost.UseUrls("http://127.0.0.1:0");var config=new ConfigurationBuilder().AddInMemoryCollection(new Dictionary<string,string?>{{"Monergy:ExecutionZone","CI_EPHEMERAL"}}).Build();builder.Services.AddSingleton(new TenantAccessClient(config,new HttpClient(authority)));builder.Services.AddSingleton(new TenantBoundaryOptions{Service="evidence",CapabilityPrefix="evidence.",ProbeUrl="http://127.0.0.1:5111/",CustomerTenants=new Dictionary<string,string>{{"foreign-customer","T002"},{"customer-one","T001"}}});builder.Services.AddSingleton<IDocumentMonitoringRepository>(corrupt?new Corrupt(repo):repo);builder.Services.AddSingleton<IClassificationMonitoringRepository>(processing);var app=builder.Build();app.UseMiddleware<TenantBoundaryMiddleware>();app.MapPost("/contracts/cid-020/v1",()=>new{executed=true});app.MapDocumentMonitoring();app.MapClassificationMonitoring();await app.StartAsync();var url=app.Services.GetRequiredService<IServer>().Features.Get<IServerAddressesFeature>()!.Addresses.Single();var client=new HttpClient{BaseAddress=new Uri(url)};client.DefaultRequestHeaders.Add("X-Monergy-Tenant","T001");client.DefaultRequestHeaders.Add("X-Monergy-Session","admin-session");return new(app,client,authority);}public async ValueTask DisposeAsync(){client.Dispose();await app.DisposeAsync();}}
}
